import { NextResponse } from "next/server"
import { verifyAdminPassword } from "@/lib/admin-password"
import { ADMIN_SESSION_COOKIE_NAME, createAdminSessionToken } from "@/lib/admin-session"
import {
  isAdminVerificationRateLimited,
  registerAdminVerificationFailedAttempt,
  clearAdminVerificationFailures,
} from "@/lib/admin-rate-limit-store"

interface VerifyRequestBody {
  password?: string
}

function getClientKey(request: Request) {
  const forwardedFor = request.headers.get("x-forwarded-for")
  if (forwardedFor) {
    const firstIp = forwardedFor.split(",")[0]?.trim()
    if (firstIp) {
      return firstIp
    }
  }

  const realIp = request.headers.get("x-real-ip")
  if (realIp) {
    return realIp
  }

  return "unknown-client"
}

export async function POST(request: Request) {
  const clientKey = getClientKey(request)

  if (await isAdminVerificationRateLimited(clientKey)) {
    return NextResponse.json(
      { ok: false, message: "인증 시도가 너무 많습니다. 잠시 후 다시 시도해주세요." },
      { status: 429 }
    )
  }

  try {
    const body = (await request.json()) as VerifyRequestBody
    const password = typeof body?.password === "string" ? body.password : ""

    const isValid = verifyAdminPassword(password)
    if (!isValid) {
      await registerAdminVerificationFailedAttempt(clientKey)
      return NextResponse.json(
        { ok: false, message: "비밀번호가 올바르지 않습니다." },
        { status: 401 }
      )
    }

    await clearAdminVerificationFailures(clientKey)

    const { token, maxAge } = createAdminSessionToken()
    const response = NextResponse.json({ ok: true })

    response.cookies.set({
      name: ADMIN_SESSION_COOKIE_NAME,
      value: token,
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite: "lax",
      path: "/",
      maxAge,
    })

    return response
  } catch {
    await registerAdminVerificationFailedAttempt(clientKey)
    return NextResponse.json(
      { ok: false, message: "잘못된 요청입니다." },
      { status: 400 }
    )
  }
}
