import "server-only"

import { mkdir, readFile, rename, writeFile } from "node:fs/promises"
import { dirname, join } from "node:path"

export const ADMIN_VERIFY_RATE_LIMIT_WINDOW_MS = 5 * 60 * 1000
export const ADMIN_VERIFY_MAX_FAILED_ATTEMPTS = 8

interface AdminRateLimitEntry {
  count: number
  resetAt: number
}

interface AdminRateLimitStoreData {
  entries: Record<string, AdminRateLimitEntry>
}

const ADMIN_RATE_LIMIT_FILE_PATH = join(process.cwd(), "data", "admin-rate-limit.json")
let writeQueue: Promise<void> = Promise.resolve()

function normalizeStore(raw: unknown): AdminRateLimitStoreData {
  if (!raw || typeof raw !== "object") {
    return { entries: {} }
  }

  const source = raw as Record<string, unknown>
  const rawEntries = source.entries

  if (!rawEntries || typeof rawEntries !== "object" || Array.isArray(rawEntries)) {
    return { entries: {} }
  }

  const entries: Record<string, AdminRateLimitEntry> = {}

  for (const [clientKey, value] of Object.entries(rawEntries as Record<string, unknown>)) {
    if (!clientKey.trim() || !value || typeof value !== "object") {
      continue
    }

    const candidate = value as Record<string, unknown>
    const count =
      typeof candidate.count === "number" && Number.isFinite(candidate.count)
        ? Math.max(0, Math.floor(candidate.count))
        : 0
    const resetAt =
      typeof candidate.resetAt === "number" && Number.isFinite(candidate.resetAt)
        ? Math.floor(candidate.resetAt)
        : 0

    if (count <= 0 || resetAt <= 0) {
      continue
    }

    entries[clientKey] = {
      count,
      resetAt,
    }
  }

  return { entries }
}

function enqueueWrite<T>(job: () => Promise<T>): Promise<T> {
  const execution = writeQueue.then(job, job)
  writeQueue = execution.then(
    () => undefined,
    () => undefined
  )

  return execution
}

async function ensureStoreFile() {
  await mkdir(dirname(ADMIN_RATE_LIMIT_FILE_PATH), { recursive: true })

  try {
    await readFile(ADMIN_RATE_LIMIT_FILE_PATH, "utf-8")
  } catch {
    await writeFile(
      ADMIN_RATE_LIMIT_FILE_PATH,
      JSON.stringify({ entries: {} }, null, 2),
      "utf-8"
    )
  }
}

async function readStore(): Promise<AdminRateLimitStoreData> {
  await ensureStoreFile()

  try {
    const raw = await readFile(ADMIN_RATE_LIMIT_FILE_PATH, "utf-8")
    const parsed = normalizeStore(JSON.parse(raw))
    const now = Date.now()
    const activeEntries: Record<string, AdminRateLimitEntry> = {}
    let changed = false

    for (const [clientKey, entry] of Object.entries(parsed.entries)) {
      if (entry.resetAt <= now) {
        changed = true
        continue
      }

      activeEntries[clientKey] = entry
    }

    if (changed) {
      await writeStore({ entries: activeEntries })
    }

    return { entries: activeEntries }
  } catch {
    return { entries: {} }
  }
}

async function writeStore(nextData: AdminRateLimitStoreData): Promise<AdminRateLimitStoreData> {
  await ensureStoreFile()

  const normalized = normalizeStore(nextData)
  const tempPath = `${ADMIN_RATE_LIMIT_FILE_PATH}.tmp`

  await writeFile(tempPath, JSON.stringify(normalized, null, 2), "utf-8")
  await rename(tempPath, ADMIN_RATE_LIMIT_FILE_PATH)

  return normalized
}

export async function isAdminVerificationRateLimited(clientKey: string): Promise<boolean> {
  const store = await readStore()
  const entry = store.entries[clientKey]

  if (!entry) {
    return false
  }

  return entry.count >= ADMIN_VERIFY_MAX_FAILED_ATTEMPTS
}

export async function registerAdminVerificationFailedAttempt(clientKey: string): Promise<void> {
  await enqueueWrite(async () => {
    const store = await readStore()
    const now = Date.now()
    const existing = store.entries[clientKey]
    const nextEntries = { ...store.entries }

    if (!existing || existing.resetAt <= now) {
      nextEntries[clientKey] = {
        count: 1,
        resetAt: now + ADMIN_VERIFY_RATE_LIMIT_WINDOW_MS,
      }
    } else {
      nextEntries[clientKey] = {
        count: existing.count + 1,
        resetAt: existing.resetAt,
      }
    }

    await writeStore({ entries: nextEntries })
  })
}

export async function clearAdminVerificationFailures(clientKey: string): Promise<void> {
  await enqueueWrite(async () => {
    const store = await readStore()

    if (!(clientKey in store.entries)) {
      return
    }

    const nextEntries = { ...store.entries }
    delete nextEntries[clientKey]

    await writeStore({ entries: nextEntries })
  })
}