import "server-only"

import { scryptSync, timingSafeEqual } from "node:crypto"

const DEFAULT_ADMIN_PASSWORD_HASH =
  "scrypt$cd361942551bb5efdcfe25cc131c82ac$5Xcl6kicf8HNYc-UvqPTG-LRGN_H6JFY6riQnaP4JKA"

function parsePasswordHash(passwordHash: string) {
  const [algorithm, salt, hash] = passwordHash.split("$")

  if (algorithm !== "scrypt" || !salt || !hash) {
    return null
  }

  return {
    salt,
    hash: Buffer.from(hash, "base64url"),
  }
}

export function verifyAdminPassword(input: string) {
  const normalizedInput = input.normalize("NFC").trim()
  if (!normalizedInput) {
    return false
  }

  const configuredHash = process.env.ADMIN_PASSWORD_HASH || DEFAULT_ADMIN_PASSWORD_HASH
  const parsed = parsePasswordHash(configuredHash)

  if (!parsed) {
    return false
  }

  const derived = scryptSync(normalizedInput, parsed.salt, parsed.hash.length)
  return timingSafeEqual(derived, parsed.hash)
}
